int main(){
    string S,T; cin>>S>>T;
    int n=S.size(), m=T.size();
    const int INF=INT_MAX/4;
    vector<int> bi(26,INF), bk(26,INF);
    for(int i=2;i<=n;i++){int c=S[i-1]-'a'; bi[c]=min(bi[c],i);}
    for(int k=1;k<=m-1;k++){int c=T[m-k-1]-'a'; bk[c]=min(bk[c],k);}
    long long best=LLONG_MAX; int bc=-1;
    for(int c=0;c<26;c++){
        if(bi[c]>=INF||bk[c]>=INF) continue;
        long long L=(long long)bi[c]+bk[c];
        if(L<best){best=L; bc=c;}
    }
    if(bc<0){cout<<-1<<"\n"; return 0;}
    int i2=bi[bc], k=bk[bc];
    cout<<S.substr(0,i2)+T.substr(m-k)<<"\n";
}

#include <bits/stdc++.h>
