int main(){
    string s; int k;
    cin>>s>>k;
    int n=s.size();
    for(int i=0;i<n && k>0;i++){
        int best=i;
        for(int j=i;j<n && j-i<=k;j++)
            if(s[j]>s[best]) best=j;   // strictly greater keeps the nearest max
        for(int j=best;j>i;j--) swap(s[j],s[j-1]);
        k-=best-i;
    }
    cout<<s<<"\n";
}

