// g(n) = max coins for the player to move with n coins left.
// Odd n, or n = 0 mod 4 (n > 4): take one coin.  n = 2 mod 4 or n = 4: take half.
long long g(long long n){
    if(n==0) return 0;
    if(n%2==1 || (n%4==0 && n!=4)) return 1 + (n-1 - g(n-1));
    long long h=n/2;
    return h + (h - g(h));
}
int main(){
    int T; cin>>T;
    while(T--){ long long n; cin>>n; cout<<g(n)<<"\n"; }
}

