        int n; scanf("%d",&n);
        map<long long,int> cnt;
        for(int i=0;i<n;i++){ long long a; scanf("%lld",&a); cnt[a]++; }
        vector<long long> P;                       // one entry per pair of equal values
        for(auto &[v,c]:cnt) for(int k=0;k<c/2;k++) P.push_back(v);
        int m=P.size();
        if(m<4){ puts("NO"); continue; }
        long long o1=(P[m-2]-P[0])*(P[m-1]-P[1]);  // x from (P0,P[m-2]), y from (P1,P[m-1])
        long long o2=(P[m-1]-P[0])*(P[m-2]-P[1]);  // x from (P0,P[m-1]), y from (P1,P[m-2])
        long long x1,x2,y1,y2;
        if(o1>=o2){ x1=P[0]; x2=P[m-2]; y1=P[1]; y2=P[m-1]; }
        else      { x1=P[0]; x2=P[m-1]; y1=P[1]; y2=P[m-2]; }
        puts("YES");
        printf("%lld %lld %lld %lld %lld %lld %lld %lld\n", x1,y1, x1,y2, x2,y1, x2,y2);
    }
