int main(){
    int n; scanf("%d",&n);
    vector<vector<long long>> t(n);
    vector<long long> all;
    for(int i=0;i<n;i++){
        int k; scanf("%d",&k);
        t[i].resize(k);
        for(auto &x:t[i]){ scanf("%lld",&x); all.push_back(x); }
    }
    sort(all.begin(),all.end());
    long long N=all.size(), good=0;
    for(auto &tw:t)
        for(size_t j=0;j+1<tw.size();j++){
            size_t idx=lower_bound(all.begin(),all.end(),tw[j])-all.begin();
            if(idx+1<all.size() && all[idx+1]==tw[j+1]) good++;   // tw[j+1] is the next larger block
        }
    long long s = (N - n) - good;   // every non-sorted adjacency must be split
    long long c = n + s - 1;        // towers created by splits must all be combined
    printf("%lld %lld\n", s, c);
}

