    for(auto &x:p) cin>>x;
    for(auto &x:c) cin>>x;
    vector<int> ord(n); iota(ord.begin(),ord.end(),0);
    sort(ord.begin(),ord.end(),[&](int i,int j){return p[i]<p[j];});
