}

#include <bits/stdc++.h>
using namespace std;
int main(){
    long long cnt; cin>>cnt;                 // number of integers, a power of 4 (4^k)
    vector<long long> a(cnt);
    for(auto &x:a) cin>>x;
    sort(a.rbegin(),a.rend());               // descending
    int k=0; while((1LL<<(2*k))<cnt) k++;    // cnt = 4^k
    long long ans=a[0]*(k+1);                // the global max is a block max on every level
    long long idx=1, block=3;                // level j introduces 3*4^(j-1) new block maxima
    for(int j=1;j<=k;j++){
        for(long long t=0;t<block;t++) ans+=a[idx++]*(k+1-j);
        block*=4;
    }
    cout<<ans<<"\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; long long k; cin>>n>>k;
    vector<long long> a(n), b(n), cap(n);
    for(auto &x:a) cin>>x;
    for(auto &x:b) cin>>x;
    long long total=0;
    for(int i=0;i<n;i++){ cap[i]=a[i]/b[i]; total+=cap[i]; }   // max work engineer i can do with benefit >= 0
    if(total<k){ for(int i=0;i<n;i++) cout<<0<<(i+1<n?' ':'\n'); return 0; }
    vector<long long> suf(n+1,0);
    for(int i=n-1;i>=0;i--) suf[i]=suf[i+1]+cap[i];   // suf[i] = capacity of engineers i..n-1
    long long R=k;
    for(int i=0;i<n;i++){
        long long c=max(0LL, R - suf[i+1]);           // least work that later engineers cannot cover
        cout<<c<<(i+1<n?' ':'\n');
        R-=c;
    }
}

