int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        int L=0; while((1<<L)<=n) L++;          // smallest L with 2^L > n
        int N=1<<L;
        vector<int> seq;                        // Gray code, then the same code reversed
        seq.reserve(2*N);
        for(int i=0;i<N;i++) seq.push_back(i ^ (i>>1));
        for(int i=N-1;i>=0;i--) seq.push_back(seq[i]);
        int k=2*N-1;
        printf("%d\n",k);
        for(int j=1;j<=k;j++) printf("%d%c", seq[j-1]^seq[j], j<k?' ':'\n');
    }
}

