int main(){
    int n,d; scanf("%d %d",&n,&d);
    vector<long long> S(n), P(n);
    for(auto &x:S) scanf("%lld",&x);
    for(auto &x:P) scanf("%lld",&x);
    long long T=S[d-1]+P[0];             // best: our astronaut takes the largest prize
    vector<long long> others, pts;
    for(int i=0;i<n;i++) if(i!=d-1) others.push_back(S[i]);
    for(int i=1;i<n;i++) pts.push_back(P[i]);
    sort(others.begin(),others.end());   // ascending current scores
    sort(pts.begin(),pts.end());         // ascending prizes
    // maximize the number of others whose new total is <= T (two pointers)
    int i=0, j=(int)pts.size()-1; long long good=0;
    while(i<(int)others.size() && j>=0){
        if(others[i]+pts[j]<=T){ good++; i++; j--; }
        else j--;                        // pts[j] too big even for the weakest remaining astronaut
    }
    printf("%lld\n", (long long)n - good);   // rank = 1 + (others above T) = n - good
}

