#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin>>n;
    vector<int> c(n);
    for(auto &x:c) cin>>x;
    vector<int> nz;                               // nonzero costs
    int negCount=0, zeros=0;
    for(int x:c){ if(x==0) zeros++; else { nz.push_back(x); if(x<0) negCount++; } }
    if(nz.empty()){ cout<<0<<"\n"; return 0; }
    if(negCount%2==0){                            // all nonzero: product is positive
        for(size_t i=0;i<nz.size();i++) cout<<nz[i]<<(i+1<nz.size()?' ':'\n');
        return 0;
    }
    // odd number of negatives: drop the negative closest to zero (largest value)
    int drop=-1;
    for(int i=0;i<(int)nz.size();i++) if(nz[i]<0 && (drop<0 || nz[i]>nz[drop])) drop=i;
    if(nz.size()>1){
        bool first=true;
        for(int i=0;i<(int)nz.size();i++) if(i!=drop){
            if(!first) cout<<' ';
            cout<<nz[i]; first=false;
        }
        cout<<"\n";
        return 0;
    }
    // single negative and nothing else
    if(zeros>0) cout<<0<<"\n";
    else cout<<nz[0]<<"\n";
}

