    for(auto &x:a) cin>>x;
    vector<bool> isAuc(n,false);
    for(int i=0;i<m;i++){ int b; cin>>b; isAuc[b-1]=true; }
    vector<long long> reg, auc;
    for(int i=0;i<n;i++) (isAuc[i]?auc:reg).push_back(a[i]);
    sort(auc.rbegin(),auc.rend());                // auctions, largest first
    long long S=0;
    for(long long x:reg) S+=x;                    // regular questions first: they cannot be raised
    if(reg.empty() && !auc.empty()){              // the very first pick cannot be raised
        S=auc[0];
        auc.erase(auc.begin());
    }
    for(long long p:auc)
        S = (S>p) ? 2*S : S+p;                    // raise the price to S (doubling), else take it at base price
    cout<<S<<"\n";
}

