    for(int i=0;i<n;i++) cin>>from[i]>>to[i]>>t[i];
    set<pair<string,string>> friends;
    for(int i=0;i<n;i++)
        for(int j=i+1;j<n;j++){
            // message j answers message i if it goes back and 0 < t_j - t_i <= d
            if(from[j]==to[i] && to[j]==from[i] && t[j]-t[i]>0 && t[j]-t[i]<=d){
