int main(){
    int n; scanf("%d",&n);
    vector<pair<int,int>> e(n-1);
    vector<vector<pair<int,int>>> adj(n+1);           // (neighbour, edge id)
    vector<int> deg(n+1,0);
    for(int i=0;i<n-1;i++){
        scanf("%d %d",&e[i].first,&e[i].second);
        adj[e[i].first].push_back({e[i].second,i});
        adj[e[i].second].push_back({e[i].first,i});
        deg[e[i].first]++; deg[e[i].second]++;
    }
    vector<int> lab(n-1,-1);
    int hub=-1;
    for(int v=1;v<=n;v++) if(deg[v]>=3){ hub=v; break; }
    if(hub!=-1){
        // three edges at the hub get 0,1,2: no path can contain all three, so max MEX is 2
        int next=3;
        for(int k=0;k<(int)adj[hub].size();k++){
            int id=adj[hub][k].second;
            lab[id] = (k<3) ? k : next++;
        }
        for(int i=0;i<n-1;i++) if(lab[i]<0) lab[i]=next++;
    } else {
        // path: label along the path from one end
        int start=1;
        for(int v=1;v<=n;v++) if(deg[v]==1){ start=v; break; }
        int cur=start, prevEdge=-1, label=0;
        while(true){
            int nxtEdge=-1, nxtNode=-1;
            for(auto [to,id]:adj[cur]) if(id!=prevEdge){ nxtEdge=id; nxtNode=to; break; }
            if(nxtEdge<0) break;
            lab[nxtEdge]=label++;
            prevEdge=nxtEdge; cur=nxtNode;
        }
    }
    for(int i=0;i<n-1;i++) printf("%d\n", lab[i]);
}

