using namespace std;
int main(){
    int t; scanf("%d",&t);
    static char buf[200005];
    while(t--){
        scanf("%s",buf);
        int n=strlen(buf);
        vector<int> pos;                       // positions of 'B'
        for(int i=0;i<n;i++) if(buf[i]=='B') pos.push_back(i);
        int m=pos.size();
        if(m==0){ puts("0"); continue; }
        // blocks b[0..m]: b[i] = number of A's between B_i and B_{i+1} (B_0 is the left edge)
        vector<long long> b(m+1);
        b[0]=pos[0];
        for(int i=1;i<m;i++) b[i]=pos[i]-pos[i-1]-1;
        b[m]=n-1-pos[m-1];
        const long long NEG=LLONG_MIN/4;
        // dp[c]: best gain so far; c=1 means the last B chose to eat right (covers b[i])
        long long dp0=0, dp1=NEG;             // before any B: block b[0] is not covered
        for(int i=1;i<=m;i++){
            long long n1 = max(dp0,dp1) + b[i];                              // B_i eats right
            long long n0 = max(dp0 + (dp0>NEG ? b[i-1] : 0),                 // B_i eats left, b[i-1] free
                               dp1 + 0);                                     // b[i-1] already covered
            if(dp0<=NEG) n0 = dp1;                                           // (dp0 invalid only when prior B ate right)
            dp0=n0; dp1=n1;
        }
        printf("%lld\n", max(dp0,dp1));
    }
}

